const body = ($input.first().json.body) || {};
const errors = [];

const orderId = body.orderId ? String(body.orderId).trim() : '';
if (!orderId) errors.push('orderId is required');

const modeOfPayment = body.modeOfPayment ? String(body.modeOfPayment).trim() : 'Not specified';

const customerEmail = body.customerEmail ? String(body.customerEmail).trim() : '';
if (!customerEmail) {
  errors.push('customerEmail is required');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)) {
  errors.push('customerEmail must be a valid email address');
}

const rawItems = Array.isArray(body.items) ? body.items : [];
if (rawItems.length === 0) errors.push('items must be a non-empty array');

const items = [];
rawItems.forEach((it, idx) => {
  const product = (it && it.product) ? String(it.product).trim() : '';
  const quantity = Number(it && it.quantity);
  if (!product) errors.push(`items[${idx}].product is required`);
  if (!quantity || quantity <= 0 || !Number.isFinite(quantity)) {
    errors.push(`items[${idx}].quantity must be a positive number`);
  }
  if (product && quantity > 0) items.push({ product, quantity });
});

return [{
  json: {
    valid: errors.length === 0,
    errors,
    orderId,
    modeOfPayment,
    customerEmail,
    items,
    receivedAt: new Date().toISOString()
  }
}];

const order = $('Validate Order Input').first().json;
const salesRows = $('Get Sales Log (Dup Check)').all()
  .map(i => i.json)
  .filter(r => r && r.OrderId);

const isDuplicate = salesRows.some(r => String(r.OrderId).trim() === order.orderId);

return [{ json: { ...order, isDuplicate } }];

const order = $('Check Duplicate Order').first().json;
const inventoryRows = $('Get All Inventory').all()
  .map(i => i.json)
  .filter(r => r && r.Product);

const results = order.items.map(item => {
  const row = inventoryRows.find(
    r => String(r.Product).trim().toLowerCase() === item.product.toLowerCase()
  );

  if (!row) {
    return {
      orderId: order.orderId,
      modeOfPayment: order.modeOfPayment,
      customerEmail: order.customerEmail,
      product: item.product,
      quantitySold: item.quantity,
      currentStock: null,
      remainingStock: null,
      reorderThreshold: null,
      price: null,
      status: 'unknown_product',
      issue: `Product "${item.product}" was not found in the Inventory sheet.`,
      lowStock: false
    };
  }

  const currentStock = Number(row.CurrentStock) || 0;
  const reorderThreshold = Number(row.ReorderThreshold) || 0;
  const price = Number(row['Selling Price']) || 0;
  const remainingStock = currentStock - item.quantity;

  if (remainingStock < 0) {
    return {
      orderId: order.orderId,
      modeOfPayment: order.modeOfPayment,
      customerEmail: order.customerEmail,
      product: item.product,
      quantitySold: item.quantity,
      currentStock,
      remainingStock,
      reorderThreshold,
      price,
      status: 'insufficient_stock',
      issue: `Only ${currentStock} in stock, order requested ${item.quantity}.`,
      lowStock: false
    };
  }

  return {
    orderId: order.orderId,
    modeOfPayment: order.modeOfPayment,
    customerEmail: order.customerEmail,
    product: item.product,
    quantitySold: item.quantity,
    currentStock,
    remainingStock,
    reorderThreshold,
    price,
    status: 'ok',
    issue: null,
    lowStock: remainingStock <= reorderThreshold
  };
});

return results.map(r => ({ json: r }));

const items = $input.all().map(i => i.json);
const orderId = items.length ? items[0].orderId : null;
const customerEmail = items.length ? items[0].customerEmail : null;
const modeOfPayment = items.length ? items[0].modeOfPayment : null;

const fulfilled = items.filter(i => i.status === 'ok');
const issues = items.filter(i => i.status !== 'ok');

const totalRevenue = fulfilled.reduce(
  (sum, i) => sum + ((i.price || 0) * (i.quantitySold || 0)), 0
);
const roundedTotal = Math.round(totalRevenue * 100) / 100;

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const timestamp = `${pad(now.getMonth() + 1)}/${pad(now.getDate())}/${now.getFullYear()} ${pad(now.getHours())}:${pad(now.getMinutes())}`;

// Table-based layout with inline styles — the only way to get reliable left/right
// alignment across email clients (Gmail, Outlook, etc. strip flexbox/grid).
const MONO = "'Courier New', Courier, monospace";
const DIVIDER = `<tr><td colspan="2" style="border-top:1px dashed #cfcfcf; padding:6px 0; line-height:0; font-size:0;">&nbsp;</td></tr>`;

function sectionTitle(label) {
  return `<tr><td colspan="2" style="font-family:${MONO}; font-size:11px; font-weight:700; letter-spacing:1px; color:#777777; padding:8px 0 4px;">${label}</td></tr>`;
}
function itemRow(left, right, color, nowrap) {
  const c = color || '#1c2b24';
  const wrapStyle = nowrap ? 'white-space:nowrap;' : 'max-width:150px;';
  return `
    <tr>
      <td style="font-family:${MONO}; font-size:13px; color:${c}; padding:3px 0; vertical-align:top;">${left}</td>
      <td style="font-family:${MONO}; font-size:12.5px; color:${c}; padding:3px 0 3px 10px; text-align:right; vertical-align:top; ${wrapStyle}">${right}</td>
    </tr>`;
}

// Quantities are short ("× 3") so they stay on one line; issue messages can run long,
// so they're allowed to wrap rather than forcing the email wider than the receipt card.
const fulfilledRows = fulfilled.map(i =>
  itemRow(escapeHtml(i.product), '&times; ' + escapeHtml(i.quantitySold), null, true)
).join('');
const issueRows = issues.map(i =>
  itemRow(escapeHtml(i.product), escapeHtml(i.issue || i.status), '#a3352b', false)
).join('');

const emailHtml = `
<div style="max-width:380px; margin:0 auto; background:#ffffff; border:1px solid #e3e3e3; border-radius:6px; padding:22px 20px; font-family:${MONO};">
  <div style="text-align:center; margin-bottom:4px;">
    <div style="font-weight:700; font-size:15px; letter-spacing:1.5px; color:#1c2b24;">GENERAL STORE</div>
    <div style="color:#8a8a8a; font-size:11px; margin-top:5px;">Order ${escapeHtml(orderId || '')}</div>
    <div style="color:#8a8a8a; font-size:11px;">${timestamp}${modeOfPayment ? ' &middot; ' + escapeHtml(modeOfPayment) : ''}</div>
  </div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; margin-top:10px;">
    ${DIVIDER}
    ${fulfilled.length ? sectionTitle('ITEMS') + fulfilledRows : ''}
    ${issues.length ? DIVIDER + sectionTitle('NOT FULFILLED') + issueRows : ''}
    ${DIVIDER}
    <tr>
      <td style="font-family:${MONO}; font-size:15px; font-weight:700; color:#1c2b24; padding-top:4px;">TOTAL</td>
      <td style="font-family:${MONO}; font-size:15px; font-weight:700; color:#1c2b24; padding-top:4px; text-align:right;">&#8369;${roundedTotal.toFixed(2)}</td>
    </tr>
  </table>
  <div style="text-align:center; margin-top:18px; font-family:Arial, sans-serif; font-size:12px; color:#8a8a8a; line-height:1.5;">
    Hi, thanks for your order! If anything here looks wrong, just reply to this email.
  </div>
</div>
`;

return [{
  json: {
    success: issues.length === 0,
    orderId,
    customerEmail,
    fulfilledItems: fulfilled.map(i => ({
      product: i.product, quantitySold: i.quantitySold, remainingStock: i.remainingStock
    })),
    issues: issues.map(i => ({ product: i.product, status: i.status, issue: i.issue })),
    totalRevenue: roundedTotal,
    emailHtml,
    processedAt: new Date().toISOString()
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r && r.Product);

const low = rows.filter(r => {
  const flagged = String(r.RestockNeeded).trim().toUpperCase() === 'TRUE';
  const belowThreshold = Number(r.CurrentStock) <= Number(r.ReorderThreshold);
  return flagged || belowThreshold;
});

const today = new Date().toLocaleDateString();
let text;
let html;

if (low.length === 0) {
  text = `✅ Daily Inventory Check (${today})

All products are above their reorder threshold. No action needed.`;
  html = `<p>✅ All products are above their reorder threshold. No action needed.</p>`;
} else {
  const lines = low.map(r => `• ${r.Product}: ${r.CurrentStock} left (reorder at ${r.ReorderThreshold})`);
  text = `📋 Daily Low-Stock Digest (${today})

${low.length} item(s) need attention:

${lines.join('\n')}`;
  html = `<p>${low.length} item(s) need attention:</p>` +
    `<table border="1" cellpadding="6" style="border-collapse:collapse">` +
    `<tr><th>Product</th><th>Current Stock</th><th>Reorder Threshold</th></tr>` +
    low.map(r => `<tr><td>${r.Product}</td><td>${r.CurrentStock}</td><td>${r.ReorderThreshold}</td></tr>`).join('') +
    `</table>`;
}

return [{ json: { text, html, lowStockCount: low.length } }];

let rows = [];
try {
  rows = $input.all().map(i => i.json).filter(r => r && r['Product Name']);
} catch (e) {
  rows = [];
}

function parseDate(value) {
  if (!value) return null;
  const raw = String(value).trim();
  let d = new Date(raw);
  if (!isNaN(d.getTime())) return d;
  d = new Date(raw.replace(' ', 'T'));
  if (!isNaN(d.getTime())) return d;
  return null;
}

const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

const recent = rows.filter(r => {
  const d = parseDate(r.Date);
  return d !== null && d >= sevenDaysAgo;
});

const byProduct = {};
let totalUnits = 0;
let totalRevenue = 0;

recent.forEach(r => {
  const qty = Number(r['Quantity Sold']) || 0;
  const rev = Number(r.Revenue) || 0;
  totalUnits += qty;
  totalRevenue += rev;
  const key = String(r['Product Name'] || 'Unknown');
  if (!byProduct[key]) byProduct[key] = { units: 0, revenue: 0, orders: 0 };
  byProduct[key].units += qty;
  byProduct[key].revenue += rev;
  byProduct[key].orders += 1;
});

const ranked = Object.entries(byProduct)
  .map(([product, stats]) => ({ product, ...stats }))
  .sort((a, b) => b.units - a.units);

const top5 = ranked.slice(0, 5);

const lines = top5.map((p, idx) =>
  (idx + 1) + '. ' + p.product + ' - ' + p.units + ' units, $' + p.revenue.toFixed(2) + ' revenue (' + p.orders + ' orders)'
);

const text = 'Weekly Sales Report (last 7 days)\n\n' +
  'Total units sold: ' + totalUnits + '\n' +
  'Total revenue: $' + totalRevenue.toFixed(2) + '\n' +
  'Orders logged: ' + recent.length + '\n\n' +
  'Top products:\n' + (lines.join('\n') || 'No sales recorded this week.');

const tableRows = top5.map((p, idx) =>
  '<tr><td>' + (idx + 1) + '</td><td>' + p.product + '</td><td>' + p.units + '</td><td>$' + p.revenue.toFixed(2) + '</td><td>' + p.orders + '</td></tr>'
).join('');

const html = '<h2>Weekly Sales Report</h2>' +
  '<p>Total units sold: <b>' + totalUnits + '</b><br>Total revenue: <b>$' + totalRevenue.toFixed(2) + '</b><br>' +
  'Orders logged: <b>' + recent.length + '</b></p>' +
  '<h3>Top Products</h3>' +
  '<table border="1" cellpadding="6" style="border-collapse:collapse">' +
  '<tr><th>#</th><th>Product</th><th>Units</th><th>Revenue</th><th>Orders</th></tr>' +
  tableRows +
  '</table>';

return [{
  json: {
    text: text,
    html: html,
    totalUnits: totalUnits,
    totalRevenue: Math.round(totalRevenue * 100) / 100,
    orderCount: recent.length
  }
}];

const data = $input.first().json;
const workflowName = (data.workflow && data.workflow.name) || 'Inventory & Sales Automation';
const nodeName = (data.execution && data.execution.lastNodeExecuted) || 'Unknown node';
const message = (data.execution && data.execution.error && data.execution.error.message)
  || JSON.stringify(data).slice(0, 300);

return [{
  json: {
    text: `🆘 Workflow Error

Workflow: ${workflowName}
Failed node: ${nodeName}
Error: ${message}
Time: ${new Date().toLocaleString()}`
  }
}];

// Status only, with the exact count revealed just when it matters (at/under the
// reorder threshold) — healthy stock stays hidden so the public demo doesn't leak
// full inventory numbers, but a shopper can see "how few" once it's actually low.
const rows = $input.all().map(i => i.json).filter(r => r && r.Product);
return rows.map(r => {
  const stock = Number(r['CurrentStock']) || 0;
  const threshold = Number(r['ReorderThreshold']) || 0;
  let status = 'in_stock';
  if (stock <= 0) status = 'out_of_stock';
  else if (stock <= threshold) status = 'low_stock';

  const result = { product: String(r.Product).trim(), status };
  if (status !== 'in_stock') {
    result.quantity = Math.max(stock, 0);
  }
  return { json: result };
});
